#!/usr/bin/env node
/**
 * figma-sync.mjs
 *
 * Sincroniza tokens do Figma para o projeto local.
 * Atualiza: dock-ds.config.json (cores), DESIGN_SYSTEM.md (header), figma-node-data.json (raw)
 *
 * Uso:
 *   FIGMA_TOKEN=xxx FIGMA_FILE_ID=yyy npm run figma:sync
 *   npx @dock-tech/shared-copilot-front-lib figma-sync --file-id=xxx --token=yyy
 *
 * Env vars:
 *   FIGMA_TOKEN     — Personal access token do Figma
 *   FIGMA_FILE_ID   — ID do arquivo Figma (ex: ENnwAECm4eFvT0pLXRVQXd)
 *   FIGMA_NODE_IDS  — (opcional) IDs de nós específicos separados por vírgula
 */

import { readFileSync, writeFileSync, existsSync } from 'fs';
import { join } from 'path';
import { argv } from 'process';

// === Config ===

const FIGMA_API_BASE = 'https://api.figma.com/v1';

function getEnvOrArg(envName, argName) {
  const env = process.env[envName];
  if (env) return env;

  const arg = argv.find((a) => a.startsWith(`--${argName}=`));
  if (arg) return arg.split('=')[1];

  return null;
}

const FIGMA_TOKEN = getEnvOrArg('FIGMA_TOKEN', 'token');
const FIGMA_FILE_ID = getEnvOrArg('FIGMA_FILE_ID', 'file-id');
const PROJECT_ROOT = process.cwd();

// === Validation ===

if (!FIGMA_TOKEN || !FIGMA_FILE_ID) {
  console.error(`
❌ Variáveis obrigatórias não definidas:
   FIGMA_TOKEN=${FIGMA_TOKEN ? '✓' : '✗ (faltando)'}
   FIGMA_FILE_ID=${FIGMA_FILE_ID ? '✓' : '✗ (faltando)'}

Uso:
   FIGMA_TOKEN=figd_xxx FIGMA_FILE_ID=abc123 npm run figma:sync
`);
  process.exit(1);
}

// === Figma API ===

async function figmaFetch(endpoint) {
  const url = `${FIGMA_API_BASE}${endpoint}`;
  const res = await fetch(url, {
    headers: { 'X-Figma-Token': FIGMA_TOKEN },
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Figma API ${res.status}: ${body}`);
  }

  return res.json();
}

async function getFileStyles() {
  return figmaFetch(`/files/${FIGMA_FILE_ID}/styles`);
}

async function getFileNodes(nodeIds) {
  const ids = nodeIds.join(',');
  return figmaFetch(`/files/${FIGMA_FILE_ID}/nodes?ids=${encodeURIComponent(ids)}`);
}

async function getFile() {
  return figmaFetch(`/files/${FIGMA_FILE_ID}`);
}

// === Color Extraction ===

function rgbaToHex({ r, g, b, a = 1 }) {
  const toHex = (v) =>
    Math.round(v * 255)
      .toString(16)
      .padStart(2, '0');
  const hex = `#${toHex(r)}${toHex(g)}${toHex(b)}`;
  return a < 1 ? `${hex}${toHex(a)}` : hex;
}

function extractColorsFromNode(node, colors = new Set()) {
  // Fills
  if (node.fills && Array.isArray(node.fills)) {
    for (const fill of node.fills) {
      if (fill.type === 'SOLID' && fill.color) {
        colors.add(rgbaToHex(fill.color));
      }
    }
  }

  // Strokes
  if (node.strokes && Array.isArray(node.strokes)) {
    for (const stroke of node.strokes) {
      if (stroke.type === 'SOLID' && stroke.color) {
        colors.add(rgbaToHex(stroke.color));
      }
    }
  }

  // Children (recursive)
  if (node.children && Array.isArray(node.children)) {
    for (const child of node.children) {
      extractColorsFromNode(child, colors);
    }
  }

  return colors;
}

function extractFontsFromNode(node, fonts = new Set()) {
  if (node.style && node.style.fontFamily) {
    fonts.add(node.style.fontFamily);
  }

  if (node.children && Array.isArray(node.children)) {
    for (const child of node.children) {
      extractFontsFromNode(child, fonts);
    }
  }

  return fonts;
}

// === File Updates ===

function updateDockDsConfig(colors, fonts) {
  const configPath = join(PROJECT_ROOT, 'dock-ds.config.json');
  let config = {};

  if (existsSync(configPath)) {
    config = JSON.parse(readFileSync(configPath, 'utf-8'));
  }

  const oldColors = config.tokens?.colors || [];
  const newColors = [...new Set([...oldColors, ...colors])].sort();

  const oldFonts = config.tokens?.fonts?.allowed || [];
  const newFonts = [...new Set([...oldFonts, ...fonts])].sort();

  // Detect diff
  const addedColors = newColors.filter((c) => !oldColors.includes(c));
  const addedFonts = newFonts.filter((f) => !oldFonts.includes(f));

  if (!config.tokens) config.tokens = {};
  config.tokens.colors = newColors;
  if (!config.tokens.fonts) config.tokens.fonts = {};
  config.tokens.fonts.allowed = newFonts;

  writeFileSync(configPath, JSON.stringify(config, null, 2) + '\n', 'utf-8');

  return { addedColors, addedFonts, totalColors: newColors.length, totalFonts: newFonts.length };
}

function updateFigmaNodeData(fileData) {
  const dataPath = join(PROJECT_ROOT, 'figma-node-data.json');
  writeFileSync(dataPath, JSON.stringify(fileData, null, 2) + '\n', 'utf-8');
}

function updateDesignSystemMdTimestamp() {
  const dsPath = join(PROJECT_ROOT, 'DESIGN_SYSTEM.md');
  if (!existsSync(dsPath)) return;

  let content = readFileSync(dsPath, 'utf-8');
  const today = new Date().toISOString().split('T')[0];

  // Update "Última atualização" date
  content = content.replace(
    /\*\*Última atualização:\*\* \d{4}-\d{2}-\d{2}/,
    `**Última atualização:** ${today}`
  );

  writeFileSync(dsPath, content, 'utf-8');
}

// === Main ===

async function main() {
  console.log('🔄 Figma Sync — Iniciando sincronização...\n');
  console.log(`   File ID: ${FIGMA_FILE_ID}`);
  console.log(`   Projeto: ${PROJECT_ROOT}\n`);

  // 1. Fetch file data
  console.log('📥 Buscando dados do arquivo Figma...');
  const fileData = await getFile();
  console.log(`   Nome: ${fileData.name}`);
  console.log(`   Última modificação: ${fileData.lastModified}\n`);

  // 2. Extract colors and fonts
  console.log('🎨 Extraindo tokens (cores e fontes)...');
  const colors = extractColorsFromNode(fileData.document);
  const fonts = extractFontsFromNode(fileData.document);

  console.log(`   Cores encontradas: ${colors.size}`);
  console.log(`   Fontes encontradas: ${fonts.size}\n`);

  // 3. Update dock-ds.config.json
  console.log('📝 Atualizando dock-ds.config.json...');
  const diff = updateDockDsConfig([...colors], [...fonts]);

  if (diff.addedColors.length > 0) {
    console.log(`   ✨ Novas cores: ${diff.addedColors.join(', ')}`);
  }
  if (diff.addedFonts.length > 0) {
    console.log(`   ✨ Novas fontes: ${diff.addedFonts.join(', ')}`);
  }
  console.log(`   Total: ${diff.totalColors} cores, ${diff.totalFonts} fontes\n`);

  // 4. Save raw node data
  console.log('💾 Salvando figma-node-data.json...');
  updateFigmaNodeData({
    fileId: FIGMA_FILE_ID,
    fileName: fileData.name,
    lastModified: fileData.lastModified,
    syncedAt: new Date().toISOString(),
    document: fileData.document,
  });

  // 5. Update DESIGN_SYSTEM.md timestamp
  console.log('📄 Atualizando timestamp do DESIGN_SYSTEM.md...');
  updateDesignSystemMdTimestamp();

  // 6. Summary
  console.log('\n✅ Figma Sync concluído!');
  console.log('─'.repeat(50));

  if (diff.addedColors.length === 0 && diff.addedFonts.length === 0) {
    console.log('   Nenhum token novo detectado. Tudo sincronizado.');
  } else {
    console.log('   ⚠️  Tokens novos adicionados. Revise dock-ds.config.json antes de commitar.');
    console.log('   Rode: npm run validate:design para verificar impacto.');
  }
}

main().catch((err) => {
  console.error('\n❌ Erro na sincronização:', err.message);
  process.exit(1);
});
